// probeRunGit runs git in dir with isolated env.
func probeRunGit(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := exec.CommandContext(context.Background(), "git", args...)
	cmd.Dir = dir
	cmd.Env = testutil.GitIsolatedEnv()
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %v in %s failed: %v\n%s", args, dir, err, out)
	}
	return string(out)
}

// probeDumpState prints everything worth knowing after each step.
func probeDumpState(t *testing.T, env *TestEnv, wtDir, label string) {
	t.Helper()
	t.Logf("======== STATE: %s ========", label)
	t.Logf("entire/* branches: %v", env.ListBranchesWithPrefix("entire/"))
	t.Logf("v1 checkpoint id: %q", env.TryGetLatestCheckpointID())

	states, _ := filepath.Glob(filepath.Join(env.RepoDir, ".git", "entire-sessions", "*.json"))
	for _, p := range states {
		b, _ := os.ReadFile(p)
		var m map[string]any
		_ = json.Unmarshal(b, &m)
		t.Logf("session state %s: phase=%v step_count=%v worktree_path=%v worktree_id=%v base_commit=%v files_touched=%v last_checkpoint_id=%v fully_condensed=%v",
			filepath.Base(p), m["phase"], m["step_count"], m["worktree_path"], m["worktree_id"],
			m["base_commit"], m["files_touched"], m["last_checkpoint_id"], m["fully_condensed"])
	}
	for _, d := range []struct{ name, dir string }{{"main", env.RepoDir}, {"worktree", wtDir}} {
		if d.dir == "" {
			continue
		}
		md, _ := filepath.Glob(filepath.Join(d.dir, ".entire", "metadata", "*"))
		t.Logf("%s .entire/metadata entries: %v", d.name, md)
	}
}

// TestProbe_WorktreeCheckpoints reproduces: session starts in the main checkout,
// agent then works and commits inside a linked worktree.
func TestProbe_WorktreeCheckpoints(t *testing.T) {
	env := NewFeatureBranchEnv(t)
	env.InitEntire()

	// ---- Turn 1: normal work in the MAIN checkout (baseline) ----
	s1 := env.NewSession()
	if err := env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(s1.ID, "add a feature", s1.TranscriptPath); err != nil {
		t.Fatalf("prompt submit: %v", err)
	}
	env.WriteFile("main.go", "package main\n")
	s1.CreateTranscript("add a feature", []FileChange{{Path: filepath.Join(env.RepoDir, "main.go"), Content: "package main\n"}})
	if err := env.SimulateStop(s1.ID, s1.TranscriptPath); err != nil {
		t.Fatalf("stop: %v", err)
	}
	probeDumpState(t, env, "", "after turn 1 in MAIN checkout")
	if len(env.ListBranchesWithPrefix("entire/")) == 0 {
		t.Fatalf("BASELINE BROKEN: no shadow branch after main-checkout turn")
	}

	// ---- Create a linked worktree, as an agent would for a PR fix ----
	wtDir := filepath.Join(t.TempDir(), "wt-fix1")
	if resolved, err := filepath.EvalSymlinks(filepath.Dir(wtDir)); err == nil {
		wtDir = filepath.Join(resolved, "wt-fix1")
	}
	probeRunGit(t, env.RepoDir, "worktree", "add", "-b", "fix/pr-1", wtDir)
	t.Logf("worktree created at %s", wtDir)
	t.Logf("worktree has .entire/settings.json: %v", fileExistsProbe(filepath.Join(wtDir, ".entire", "settings.json")))
	t.Logf("worktree has .claude/settings.json: %v", fileExistsProbe(filepath.Join(wtDir, ".claude", "settings.json")))

	// ---- Turn 2: hooks fire with cwd = the WORKTREE (Claude Code's cwd follows Claude) ----
	wtRunner := NewHookRunner(wtDir, env.ClaudeProjectDir, t)
	if err := wtRunner.SimulateUserPromptSubmitWithPromptAndTranscriptPath(s1.ID, "fix the PR", s1.TranscriptPath); err != nil {
		t.Fatalf("worktree prompt submit: %v", err)
	}
	fixPath := filepath.Join(wtDir, "fix.go")
	if err := os.WriteFile(fixPath, []byte("package main // fixed\n"), 0o600); err != nil {
		t.Fatalf("write fix: %v", err)
	}
	// Append the worktree edit to the same live transcript.
	s1.TranscriptBuilder.AddUserMessage("fix the PR")
	tid := s1.TranscriptBuilder.AddToolUse("mcp__acp__Write", fixPath, "package main // fixed\n")
	s1.TranscriptBuilder.AddToolResult(tid)
	s1.TranscriptBuilder.AddAssistantMessage("Fixed.")
	if err := s1.TranscriptBuilder.WriteToFile(s1.TranscriptPath); err != nil {
		t.Fatalf("write transcript: %v", err)
	}

	before := env.ListBranchesWithPrefix("entire/")
	if err := wtRunner.SimulateStop(s1.ID, s1.TranscriptPath); err != nil {
		t.Fatalf("worktree stop: %v", err)
	}
	after := env.ListBranchesWithPrefix("entire/")
	probeDumpState(t, env, wtDir, "after turn 2 STOP fired in WORKTREE")
	t.Logf("branches before=%v after=%v", before, after)

	// ---- Commit inside the worktree with the real git hooks ----
	probeRunGit(t, wtDir, "add", "fix.go")
	msgFile := filepath.Join(wtDir, "COMMIT_MSG_PROBE")
	if err := os.WriteFile(msgFile, []byte("fix the PR\n"), 0o600); err != nil {
		t.Fatalf("write msg: %v", err)
	}
	prep := exec.CommandContext(context.Background(), getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile, "message")
	prep.Dir = wtDir
	prep.Env = env.gitHookEnv()
	prepOut, prepErr := prep.CombinedOutput()
	t.Logf("prepare-commit-msg (in worktree) err=%v out=%s", prepErr, prepOut)
	msg, _ := os.ReadFile(msgFile)
	t.Logf("commit message after prepare hook:\n%s", msg)
	hasTrailer := strings.Contains(string(msg), "Entire-Checkpoint")
	t.Logf("TRAILER ADDED: %v", hasTrailer)

	probeRunGit(t, wtDir, "commit", "-F", msgFile, "--no-gpg-sign")
	post := exec.CommandContext(context.Background(), getTestBinary(), "hooks", "git", "post-commit")
	post.Dir = wtDir
	post.Env = env.gitHookEnv()
	postOut, postErr := post.CombinedOutput()
	t.Logf("post-commit (in worktree) err=%v out=%s", postErr, postOut)

	probeDumpState(t, env, wtDir, "after COMMIT in WORKTREE")
	t.Logf("worktree HEAD commit message:\n%s", probeRunGit(t, wtDir, "log", "-1", "--format=%B"))

	// status from both places
	for _, d := range []struct{ name, dir string }{{"main", env.RepoDir}, {"worktree", wtDir}} {
		c := exec.CommandContext(context.Background(), getTestBinary(), "status")
		c.Dir = d.dir
		c.Env = env.gitHookEnv()
		o, _ := c.CombinedOutput()
		t.Logf("---- entire status in %s ----\n%s", d.name, o)
	}
}

