	}
	return string(out)
}

func probeShadowTrees(t *testing.T, env *TestEnv) {
	t.Helper()
	for _, b := range env.ListBranchesWithPrefix("entire/") {
		if b == "entire/checkpoints/v1" {
			t.Logf("    [v1] log:\n%s", indent(probeRunGit(t, env.RepoDir, "log", "--format=%H %s", b)))
			t.Logf("    [v1] tree:\n%s", indent(probeRunGit(t, env.RepoDir, "ls-tree", "-r", "--name-only", b)))
			continue
		}
		t.Logf("    [shadow %s] head=%s tree:\n%s", b,
			strings.TrimSpace(probeRunGit(t, env.RepoDir, "rev-parse", "--short", b)),
			indent(probeRunGit(t, env.RepoDir, "ls-tree", "-r", "--name-only", b)))
	}
}

func indent(s string) string {
	var out []string
	for _, l := range strings.Split(strings.TrimRight(s, "\n"), "\n") {
		out = append(out, "        "+l)
	}
	return strings.Join(out, "\n")
}

func probeDump(t *testing.T, env *TestEnv, wtDir, label string) {
	t.Helper()
	t.Logf("======== %s ========", label)
	t.Logf("  branches: %v", env.ListBranchesWithPrefix("entire/"))
	states, _ := filepath.Glob(filepath.Join(env.RepoDir, ".git", "entire-sessions", "*.json"))
	for _, p := range states {
		b, _ := os.ReadFile(p)
		var m map[string]any
		_ = json.Unmarshal(b, &m)
		t.Logf("  state %s: phase=%v step=%v wt_path=%v wt_id=%v base=%v files=%v last_cp=%v cp_transcript_start=%v",
			filepath.Base(p), m["phase"], m["step_count"], shortPath(m["worktree_path"]), m["worktree_id"],
			shortHash(m["base_commit"]), m["files_touched"], m["last_checkpoint_id"], m["checkpoint_transcript_start"])
	}
	for _, d := range []struct{ name, dir string }{{"main", env.RepoDir}, {"wt", wtDir}} {
		if d.dir == "" {
			continue
		}
		md, _ := filepath.Glob(filepath.Join(d.dir, ".entire", "metadata", "*", "*"))
		var rel []string
		for _, m := range md {
			rel = append(rel, filepath.Base(filepath.Dir(m))+"/"+filepath.Base(m))
		}
		t.Logf("  %s .entire/metadata: %v", d.name, rel)
	}
	probeShadowTrees(t, env)
}

func shortPath(v any) string {
	s, _ := v.(string)
	if s == "" {
		return "<nil>"
	}
	return ".../" + filepath.Base(s)
}
func shortHash(v any) string {
	s, _ := v.(string)
	if len(s) > 7 {
		return s[:7]
	}
	return s
}

type probeCase struct {
	name           string
	commitSettings bool
	hooksFollowCwd bool // true: agent hooks run with cwd=worktree; false: cwd stays in main checkout
}

func TestProbe_WorktreeCheckpoints(t *testing.T) {
	for _, tc := range []probeCase{
		{"A_settings_uncommitted__hooks_in_worktree", false, true},
		{"B_settings_committed__hooks_in_worktree", true, true},
		{"C_settings_committed__hooks_stay_in_main", true, false},
	} {
		t.Run(tc.name, func(t *testing.T) { probeWorktree(t, tc) })
	}
}

func probeWorktree(t *testing.T, tc probeCase) {
	env := NewFeatureBranchEnv(t)
	env.InitEntire()
	if tc.commitSettings {
		probeRunGit(t, env.RepoDir, "add", "-f", ".entire/settings.json")
		probeRunGit(t, env.RepoDir, "commit", "-m", "add entire settings", "--no-gpg-sign", "--no-verify")
	}

	// ---- Turn 1: normal work in the MAIN checkout (baseline) ----
	s1 := env.NewSession()
	if err := env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(s1.ID, "add a feature", s1.TranscriptPath); err != nil {
		t.Fatalf("prompt submit: %v", err)
	}
	env.WriteFile("main.go", "package main\n")
	s1.CreateTranscript("add a feature", []FileChange{{Path: filepath.Join(env.RepoDir, "main.go"), Content: "package main\n"}})
	if err := env.SimulateStop(s1.ID, s1.TranscriptPath); err != nil {
		t.Fatalf("stop: %v", err)
	}
	probeDump(t, env, "", "T1 done (main checkout)")

	// ---- Linked worktree, as an agent would create for a PR fix ----
	wtParent := t.TempDir()
	if r, err := filepath.EvalSymlinks(wtParent); err == nil {
		wtParent = r
	}
	wtDir := filepath.Join(wtParent, "wt-fix1")
	probeRunGit(t, env.RepoDir, "worktree", "add", "-b", "fix/pr-1", wtDir)
	t.Logf(">> worktree %s | .entire/settings.json present: %v", wtDir,
		fileExistsProbe(filepath.Join(wtDir, ".entire", "settings.json")))

	hookDir := wtDir
	if !tc.hooksFollowCwd {
		hookDir = env.RepoDir
	}
	runner := NewHookRunner(hookDir, env.ClaudeProjectDir, t)
	t.Logf(">> agent hooks will run with cwd=%s", hookDir)

	// ---- Turn 2: the agent edits inside the worktree ----
	if err := runner.SimulateUserPromptSubmitWithPromptAndTranscriptPath(s1.ID, "fix the PR", s1.TranscriptPath); err != nil {
		t.Fatalf("wt prompt submit: %v", err)
	}
	fixPath := filepath.Join(wtDir, "fix.go")
	if err := os.WriteFile(fixPath, []byte("package main // fixed\n"), 0o600); err != nil {
		t.Fatalf("write fix: %v", err)
	}
	s1.TranscriptBuilder.AddUserMessage("fix the PR")
	tid := s1.TranscriptBuilder.AddToolUse("mcp__acp__Write", fixPath, "package main // fixed\n")
	s1.TranscriptBuilder.AddToolResult(tid)
	s1.TranscriptBuilder.AddAssistantMessage("Fixed.")
	if err := s1.TranscriptBuilder.WriteToFile(s1.TranscriptPath); err != nil {
		t.Fatalf("write transcript: %v", err)
	}
	if err := runner.SimulateStop(s1.ID, s1.TranscriptPath); err != nil {
		t.Fatalf("wt stop: %v", err)
	}
	probeDump(t, env, wtDir, "T2 done (edit made INSIDE worktree)")

	// ---- Commit inside the worktree, real git hooks ----
	probeRunGit(t, wtDir, "add", "fix.go")
	msgFile := filepath.Join(wtDir, "COMMIT_MSG_PROBE")
	if err := os.WriteFile(msgFile, []byte("fix the PR\n"), 0o600); err != nil {
		t.Fatalf("write msg: %v", err)
	}
	prep := exec.CommandContext(context.Background(), getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile, "message")
	prep.Dir = wtDir
	prep.Env = env.gitHookEnv()
	po, pe := prep.CombinedOutput()
	t.Logf(">> prepare-commit-msg in worktree: err=%v out=%q", pe, strings.TrimSpace(string(po)))
	msg, _ := os.ReadFile(msgFile)
	t.Logf(">> TRAILER ADDED: %v (message: %q)", strings.Contains(string(msg), "Entire-Checkpoint"), strings.TrimSpace(string(msg)))

	probeRunGit(t, wtDir, "commit", "-F", msgFile, "--no-gpg-sign")
	post := exec.CommandContext(context.Background(), getTestBinary(), "hooks", "git", "post-commit")
	post.Dir = wtDir
	post.Env = env.gitHookEnv()
	qo, qe := post.CombinedOutput()
	t.Logf(">> post-commit in worktree: err=%v out=%q", qe, strings.TrimSpace(string(qo)))

	probeDump(t, env, wtDir, "after COMMIT in worktree")
	t.Logf(">> worktree HEAD: %s", strings.TrimSpace(probeRunGit(t, wtDir, "rev-parse", "--short", "HEAD")))
	t.Logf(">> main HEAD:     %s", strings.TrimSpace(probeRunGit(t, env.RepoDir, "rev-parse", "--short", "HEAD")))

	for _, d := range []struct{ name, dir string }{{"main", env.RepoDir}, {"wt", wtDir}} {
		c := exec.CommandContext(context.Background(), getTestBinary(), "checkpoint", "list")
		c.Dir = d.dir
		c.Env = env.gitHookEnv()
		o, _ := c.CombinedOutput()
		t.Logf("---- checkpoint list in %s ----\n%s", d.name, indent(string(o)))
	}
}

