import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

func probeGit(t *testing.T, dir string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Env = testutil.GitIsolatedEnv()
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git %v in %s: %v\n%s", args, dir, err, out)
	}
}

// TestProbe_EphemeralWriteFromWrongWorktree records what buildTreeWithChanges
// actually does when paths.WorktreeRoot resolves to a DIFFERENT worktree than
// the one holding the touched files.
func TestProbe_EphemeralWriteFromWrongWorktree(t *testing.T) {
	mainDir := t.TempDir()
	if r, err := filepath.EvalSymlinks(mainDir); err == nil {
		mainDir = r
	}
	testutil.InitRepo(t, mainDir)
	testutil.WriteFile(t, mainDir, "shared.go", "package main // BASE\n")
	testutil.GitAdd(t, mainDir, "shared.go")
	testutil.GitCommit(t, mainDir, "init")

	wtParent := t.TempDir()
	if r, err := filepath.EvalSymlinks(wtParent); err == nil {
		wtParent = r
	}
	wtDir := filepath.Join(wtParent, "wt")
	probeGit(t, mainDir, "worktree", "add", "-b", "fix", wtDir)

	// Agent works INSIDE the worktree: edits a shared file, creates a new one.
	if err := os.WriteFile(filepath.Join(wtDir, "shared.go"), []byte("package main // AGENT EDIT\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(wtDir, "wtonly.go"), []byte("package main // AGENT NEW\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	metadataDir := filepath.Join(mainDir, ".entire", "metadata", "2026-08-31-probe")
	if err := os.MkdirAll(metadataDir, 0o750); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(metadataDir, "full.jsonl"), []byte("{}\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	repo, err := gitrepo.OpenPath(mainDir)
	if err != nil {
		t.Fatal(err)
	}
	defer repo.Close()
	head, err := repo.Head()
	if err != nil {
		t.Fatal(err)
	}

	// THE HALF-FIX: turn-end's repoRoot now points at the worktree (so these
	// paths survive filtering), but cwd — and therefore the ephemeral store's
	// own paths.WorktreeRoot call — still resolves to the main checkout.
	t.Chdir(mainDir)

	res, err := NewEphemeralStore(repo, DefaultV1Refs()).Write(context.Background(), Step{
		SessionID:         "2026-08-31-probe",
		BaseCommit:        head.Hash().String(),
		ModifiedFiles:     []string{"shared.go", "wtonly.go"},
		MetadataDir:       ".entire/metadata/2026-08-31-probe",
		MetadataDirAbs:    metadataDir,
		CommitMessage:     "agent work done in the worktree",
		AuthorName:        "T",
		AuthorEmail:       "t@t.io",
		IsFirstCheckpoint: false,
	})
	if err != nil {
		t.Fatalf("write: %v", err)
	}
	t.Logf("skipped=%v commit=%s", res.Skipped, res.CommitHash)

	c, err := repo.CommitObject(res.CommitHash)
	if err != nil {
		t.Fatal(err)
	}
	tree, err := c.Tree()
	if err != nil {
		t.Fatal(err)
	}
	t.Log("--- shadow tree entries ---")
	if err := tree.Files().ForEach(func(f *object.File) error {
		content, _ := f.Contents()
		t.Logf("  %-50s %q", f.Name, content)
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	for _, p := range []string{"shared.go", "wtonly.go"} {
		if _, ferr := tree.File(p); ferr == plumbing.ErrObjectNotFound || ferr != nil {
			t.Logf("  ABSENT from shadow tree: %s (%v)", p, ferr)
		}
	}
	t.Logf("on-disk worktree shared.go = %q", mustRead(t, filepath.Join(wtDir, "shared.go")))
	t.Logf("on-disk main     shared.go = %q", mustRead(t, filepath.Join(mainDir, "shared.go")))
}

func mustRead(t *testing.T, p string) string {
	t.Helper()
	b, err := os.ReadFile(p) //nolint:gosec // test path
	if err != nil {
		return "<missing>"
	}
	return string(b)
}
