package checkpoint

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// agentEdit is the content the agent writes inside the linked worktree.
// baseContent is what the main checkout still holds at HEAD.
const (
	baseContent = "package main // BASE\n"
	agentEdit   = "package main // AGENT EDIT\n"
	agentNew    = "package main // AGENT NEW\n"
)

func redteamGit(t *testing.T, dir string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Env = testutil.GitIsolatedEnv()
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git %v in %s: %v\n%s", args, dir, err, out)
	}
}

// setupWorktreeScenario builds a main checkout holding baseContent at HEAD and a
// linked worktree where the agent has edited shared.go and created wtonly.go.
// Returns (mainDir, wtDir, metadataDirAbs, baseCommit).
func setupWorktreeScenario(t *testing.T) (string, string, string, string) {
	t.Helper()

	mainDir := t.TempDir()
	if r, err := filepath.EvalSymlinks(mainDir); err == nil {
		mainDir = r
	}
	testutil.InitRepo(t, mainDir)
	testutil.WriteFile(t, mainDir, "shared.go", baseContent)
	testutil.GitAdd(t, mainDir, "shared.go")
	testutil.GitCommit(t, mainDir, "init")

	wtParent := t.TempDir()
	if r, err := filepath.EvalSymlinks(wtParent); err == nil {
		wtParent = r
	}
	wtDir := filepath.Join(wtParent, "wt")
	redteamGit(t, mainDir, "worktree", "add", "-b", "fix", wtDir)

	if err := os.WriteFile(filepath.Join(wtDir, "shared.go"), []byte(agentEdit), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(wtDir, "wtonly.go"), []byte(agentNew), 0o600); err != nil {
		t.Fatal(err)
	}

	metadataDir := filepath.Join(mainDir, ".entire", "metadata", "2026-08-31-wt")
	if err := os.MkdirAll(metadataDir, 0o750); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(metadataDir, "full.jsonl"), []byte("{}\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	repo, err := gitrepo.OpenPath(mainDir)
	if err != nil {
		t.Fatal(err)
	}
	defer repo.Close()
	head, err := repo.Head()
	if err != nil {
		t.Fatal(err)
	}
	return mainDir, wtDir, metadataDir, head.Hash().String()
}

// writeEphemeralFromCwd writes one ephemeral checkpoint for the agent's two
// files and returns the resulting shadow tree. cwd decides which worktree the
// store's own paths.WorktreeRoot call resolves to.
func writeEphemeralFromCwd(t *testing.T, mainDir, metadataDir, baseCommit, cwd string) *object.Tree {
	t.Helper()

	repo, err := gitrepo.OpenPath(mainDir)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { repo.Close() })

	t.Chdir(cwd)

	res, err := NewEphemeralStore(repo, DefaultV1Refs()).Write(context.Background(), Step{
		SessionID:         "2026-08-31-wt",
		BaseCommit:        baseCommit,
		ModifiedFiles:     []string{"shared.go", "wtonly.go"},
		MetadataDir:       ".entire/metadata/2026-08-31-wt",
		MetadataDirAbs:    metadataDir,
		CommitMessage:     "agent work done in the linked worktree",
		AuthorName:        "T",
		AuthorEmail:       "t@t.io",
		IsFirstCheckpoint: false,
	})
	if err != nil {
		t.Fatalf("ephemeral write: %v", err)
	}
	if res.Skipped {
		t.Fatal("ephemeral write skipped; expected a checkpoint")
	}
	commit, err := repo.CommitObject(res.CommitHash)
	if err != nil {
		t.Fatal(err)
	}
	tree, err := commit.Tree()
	if err != nil {
		t.Fatal(err)
	}
	return tree
}

func fileContentInTree(t *testing.T, tree *object.Tree, path string) (string, bool) {
	t.Helper()
	f, err := tree.File(path)
	if err != nil {
		return "", false
	}
	c, err := f.Contents()
	if err != nil {
		t.Fatalf("read %s from tree: %v", path, err)
	}
	return c, true
}

// TestEphemeralWrite_CapturesTheWorktreeThatHoldsTheFiles is the RED test for the
// cwd prerequisite (spec §2). buildTreeWithChanges resolves paths.WorktreeRoot
// ITSELF (checkpoint/ephemeral.go:791) rather than receiving turn-end's repoRoot,
// so converting only turn-end's local — the "narrow" half-fix — leaves the store
// reading the wrong worktree.
//
// The failure is NOT a deletion. Measured on origin/main:
//   - shared.go, which exists in BOTH worktrees, is captured with the MAIN
//     checkout's unmodified bytes. The checkpoint claims the file as touched
//     while recording that the agent changed nothing. Plausible-looking, wrong.
//   - wtonly.go, which exists only in the linked worktree, is silently ABSENT:
//     fileExists() fails, ephemeral.go:818-822 records a nil entry ("treat as
//     deletion"), and deleting a path that is not in the base tree is a no-op.
//
// The nil-entry/deletion branch only produces a visible deletion for a path that
// is in the base tree but missing from the resolved worktree's disk — a much
// narrower case than either of the above. A test asserting "no nil entries"
// therefore PASSES on the broken behaviour; assert content and presence instead.
func TestEphemeralWrite_CapturesTheWorktreeThatHoldsTheFiles(t *testing.T) {
	t.Run("control_cwd_in_worktree", func(t *testing.T) {
		mainDir, wtDir, metadataDir, base := setupWorktreeScenario(t)
		tree := writeEphemeralFromCwd(t, mainDir, metadataDir, base, wtDir)

		got, ok := fileContentInTree(t, tree, "shared.go")
		if !ok {
			t.Fatal("shared.go absent from shadow tree")
		}
		if got != agentEdit {
			t.Errorf("shared.go = %q, want the agent's edit %q", got, agentEdit)
		}
		if got, ok := fileContentInTree(t, tree, "wtonly.go"); !ok {
			t.Error("wtonly.go absent from shadow tree; the agent created it")
		} else if got != agentNew {
			t.Errorf("wtonly.go = %q, want %q", got, agentNew)
		}
	})

	// RED until the ephemeral store resolves the worktree from the turn's event
	// rather than from process cwd.
	t.Run("cwd_in_main_checkout", func(t *testing.T) {
		mainDir, _, metadataDir, base := setupWorktreeScenario(t)
		tree := writeEphemeralFromCwd(t, mainDir, metadataDir, base, mainDir)

		got, ok := fileContentInTree(t, tree, "shared.go")
		if !ok {
			t.Fatal("shared.go absent from shadow tree")
		}
		if got == baseContent {
			t.Errorf("shared.go captured the MAIN checkout's bytes %q: the checkpoint "+
				"claims the file as touched while recording that the agent changed nothing", got)
		}
		if got != agentEdit {
			t.Errorf("shared.go = %q, want the agent's edit %q", got, agentEdit)
		}
		if _, ok := fileContentInTree(t, tree, "wtonly.go"); !ok {
			t.Error("wtonly.go silently absent from shadow tree: fileExists() failed against " +
				"the wrong worktree, and the nil-entry 'deletion' is a no-op for a path not in the base tree")
		}
	})
