package settings

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

func pinGit(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Env = testutil.GitIsolatedEnv()
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %v in %s: %v\n%s", args, dir, err, out)
	}
	return string(out)
}

// nonDefaultScannerConfig selects goredact instead of betterleaks. Both scanner
// keys are honoured from the COMMITTED settings file only, they are fail-closed,
// and they decide which engine inspects content before it leaves the machine —
// so this is the cheapest setting whose silent loss actually matters. Defaults
// are the inverse: betterleaks on, goredact off.
const nonDefaultScannerConfig = `{
  "enabled": true,
  "redaction": {
    "betterleaks": {"enabled": false},
    "goredact": {"enabled": true}
  }
}
`

// setupSettingsPinScenario builds a main checkout whose committed settings select
// a non-default scanner engine, plus a linked worktree checked out at the commit
// BEFORE those settings existed — so the worktree's branch has no
// .entire/settings.json at all. Returns (mainDir, wtDir).
//
// That shape is not contrived. A worktree branched before the settings commit has
// it, and so does every fresh worktree of a repo enabled with `entire enable
// --local`: .entire/settings.local.json is gitignored (.entire/.gitignore:2), so
// it CANNOT be present in a new checkout.
func setupSettingsPinScenario(t *testing.T) (string, string) {
	t.Helper()

	mainDir := t.TempDir()
	if r, err := filepath.EvalSymlinks(mainDir); err == nil {
		mainDir = r
	}
	testutil.InitRepo(t, mainDir)
	testutil.WriteFile(t, mainDir, "README.md", "# repo\n")
	testutil.GitAdd(t, mainDir, "README.md")
	testutil.GitCommit(t, mainDir, "init")
	preSettings := pinGit(t, mainDir, "rev-parse", "HEAD")
	preSettings = preSettings[:40]

	if err := os.MkdirAll(filepath.Join(mainDir, ".entire"), 0o750); err != nil {
		t.Fatal(err)
	}
	testutil.WriteFile(t, mainDir, ".entire/settings.json", nonDefaultScannerConfig)
	pinGit(t, mainDir, "add", "-f", ".entire/settings.json")
	testutil.GitCommit(t, mainDir, "configure scanners")

	wtParent := t.TempDir()
	if r, err := filepath.EvalSymlinks(wtParent); err == nil {
		wtParent = r
	}
	wtDir := filepath.Join(wtParent, "wt")
	pinGit(t, mainDir, "worktree", "add", "-b", "fix", wtDir, preSettings)

	if _, err := os.Stat(filepath.Join(wtDir, ".entire", "settings.json")); !os.IsNotExist(err) {
		t.Fatalf("scenario is wrong: the worktree should have no .entire/settings.json (stat err = %v)", err)
	}
	return mainDir, wtDir
}

func assertScanners(t *testing.T, s *EntireSettings, wantBetterleaks, wantGoredact bool, what string) {
	t.Helper()
	if got := s.BetterleaksEnabled(); got != wantBetterleaks {
		t.Errorf("%s: BetterleaksEnabled() = %v, want %v", what, got, wantBetterleaks)
	}
	if got := s.GoredactEnabled(); got != wantGoredact {
		t.Errorf("%s: GoredactEnabled() = %v, want %v", what, got, wantGoredact)
	}
}

// TestLoad_WorktreeRootPinSurvivesACwdInAWorktreeWithoutSettings locks the
// property a chdir-based cwd fix must preserve: settings resolution stays pinned
// to the checkout that owns the session, so redaction config cannot silently
// change because a turn happened in a linked worktree.
//
// Why this matters more than it looks. The agent-hook admission gate
// (settings.IsSetUpAndEnabled, hook_registry.go:122) runs BEFORE
// DispatchLifecycleEvent (:210), so it resolves against the main checkout and a
// chdir cannot silently disable capture. But nothing re-checks afterwards, and
// Load's contract is "Returns default settings if no settings or preferences
// file exists" (settings.go:550) — not "disabled". So an unpinned load after a
// chdir yields DEFAULT redaction rather than an error or a no-op: admitted
// because main says enabled, then scanned with defaults because the worktree has
// no file. Silent, and on the path that decides what leaves the machine.
//
// SCOPE — read before trusting this test. It pins Load's behaviour at the
// settings layer. It does NOT catch a chdir landed at DispatchLifecycleEvent
// without the pin, because it constructs its own contexts and never dispatches a
// turn. The guard for that must live at the dispatch layer and assert the
// EFFECTIVE config of a dispatched turn; it cannot be written meaningfully until
// the chdir exists. Do not let this test's presence be read as covering that.
func TestLoad_WorktreeRootPinSurvivesACwdInAWorktreeWithoutSettings(t *testing.T) {
	// Documents the hazard executably: this is what an unpinned load does, and
	// it is Load behaving as designed — the bug would be a caller that chdirs
	// without pinning, not Load itself.
	t.Run("unpinned_follows_cwd_and_silently_falls_back_to_defaults", func(t *testing.T) {
		_, wtDir := setupSettingsPinScenario(t)
		t.Chdir(wtDir)

		s, err := Load(context.Background())
		if err != nil {
			t.Fatalf("Load: %v", err)
		}
		assertScanners(t, s, true, false, "unpinned load in a settings-less worktree")
	})

	// The property a chdir implementation must preserve.
	t.Run("pinned_keeps_the_owning_checkouts_config", func(t *testing.T) {
		mainDir, wtDir := setupSettingsPinScenario(t)
		t.Chdir(wtDir)

		s, err := Load(WithWorktreeRoot(context.Background(), mainDir))
		if err != nil {
			t.Fatalf("Load with pin: %v", err)
		}
		assertScanners(t, s, false, true, "pinned load from a settings-less worktree")
	})

	// Control: the pin is doing the work, not the scenario. Same committed
	// settings, cwd in the main checkout, no pin needed.
	t.Run("control_cwd_in_main_checkout", func(t *testing.T) {
		mainDir, _ := setupSettingsPinScenario(t)
		t.Chdir(mainDir)

		s, err := Load(context.Background())
		if err != nil {
			t.Fatalf("Load: %v", err)
		}
		assertScanners(t, s, false, true, "unpinned load in the main checkout")
	})
}
GOEOF
