		cwd = ""
	}

	// Check cache with read lock first
	gitCommonDirMu.RLock()
	if gitCommonDirCache != "" && gitCommonDirCacheDir == cwd {
		cached := gitCommonDirCache
		gitCommonDirMu.RUnlock()
