)

// TestProbe_CrossoverTurn1MainTurn2Worktree: session starts in the main
// checkout, then the agent moves into a linked worktree. initializeSession has
// already run, so WorktreePath/WorktreeID stay pinned to main while the override
// redirects this turn's capture. What does the recorded state and the shadow
// branch look like?
func TestProbe_CrossoverTurn1MainTurn2Worktree(t *testing.T) {
	env := NewFeatureBranchEnv(t)
	env.InitEntire()
	wtDir := addLinkedWorktree(t, env, "fix/pr-1")

	runner := NewHookRunner(env.RepoDir, env.ClaudeProjectDir, t)
	s := env.NewSession()

	// --- Turn 1: in the MAIN checkout, no cwd override ---
	if err := runner.SimulateUserPromptSubmitWithPromptAndTranscriptPath(s.ID, "add a feature", s.TranscriptPath); err != nil {
		t.Fatal(err)
	}
	env.WriteFile("main.go", "package main\n")
	s.CreateTranscript("add a feature", []FileChange{{Path: filepath.Join(env.RepoDir, "main.go"), Content: "package main\n"}})
	if err := runner.SimulateStop(s.ID, s.TranscriptPath); err != nil {
		t.Fatal(err)
	}
	dumpCrossover(t, env, "after T1 in MAIN")

	// --- Turn 2: cwd now names the WORKTREE ---
	if err := runner.SimulateUserPromptSubmitWithCwd(s.ID, "fix the PR", s.TranscriptPath, wtDir); err != nil {
		t.Fatal(err)
	}
	fix := filepath.Join(wtDir, "fix.go")
	if err := os.WriteFile(fix, []byte("package main // wt\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	s.TranscriptBuilder.AddUserMessage("fix the PR")
	tid := s.TranscriptBuilder.AddToolUse("mcp__acp__Write", fix, "package main // wt\n")
	s.TranscriptBuilder.AddToolResult(tid)
	if err := s.TranscriptBuilder.WriteToFile(s.TranscriptPath); err != nil {
		t.Fatal(err)
	}
	if err := runner.SimulateStopWithCwd(s.ID, s.TranscriptPath, wtDir); err != nil {
		t.Fatal(err)
	}
	dumpCrossover(t, env, "after T2 in WORKTREE")
}

func dumpCrossover(t *testing.T, env *TestEnv, label string) {
	t.Helper()
	t.Logf("======== %s ========", label)
	for _, b := range env.ListBranchesWithPrefix("entire/") {
		if b == "entire/checkpoints/v1" {
			continue
		}
		t.Logf("  shadow %s tree:\n%s", b, worktreeGit(t, env.RepoDir, "ls-tree", "-r", "--name-only", b))
	}
	states, _ := filepath.Glob(filepath.Join(env.RepoDir, ".git", "entire-sessions", "*.json"))
	for _, p := range states {
		b, _ := os.ReadFile(p)
		var m map[string]any
		_ = json.Unmarshal(b, &m)
		t.Logf("  state: wt_path=%v wt_id=%v base=%v files=%v step=%v",
			m["worktree_path"], m["worktree_id"], m["base_commit"], m["files_touched"], m["step_count"])
	}
}
