func TestProbe_CrossoverCommitLinking(t *testing.T) {
	env := NewFeatureBranchEnv(t)
	env.InitEntire()
	wtDir := addLinkedWorktree(t, env, "fix/xover")

	runner := NewHookRunner(env.RepoDir, env.ClaudeProjectDir, t)
