	if err := runner.SimulateUserPromptSubmitWithPromptAndTranscriptPath(s.ID, "feature", s.TranscriptPath); err != nil {
		t.Fatal(err)
	}
	env.WriteFile("main.go", "package main\n")
	s.CreateTranscript("feature", []FileChange{{Path: filepath.Join(env.RepoDir, "main.go"), Content: "package main\n"}})
	if err := runner.SimulateStop(s.ID, s.TranscriptPath); err != nil {
		t.Fatal(err)
	}

	// Turn 2: agent moves to the WORKTREE and edits there (no Stop yet — it
	// commits mid-turn, which is the realistic agent shape)
	if err := runner.SimulateUserPromptSubmitWithCwd(s.ID, "fix in wt", s.TranscriptPath, wtDir); err != nil {
