func addPlainWorktree(t *testing.T, env *TestEnv, branch, name string) string {
	t.Helper()
	parent := t.TempDir()
	if r, err := filepath.EvalSymlinks(parent); err == nil {
		parent = r
	}
	dir := filepath.Join(parent, name)
	worktreeGit(t, env.RepoDir, "worktree", "add", "-b", branch, dir)
	return dir
}

