// touching touchedFile, then commits touchedFile in a worktree where NO session
// lives (so exactWorktreeMatches must fail and the sibling fallback decides).
// Returns the minted checkpoint ID, "" if none.
func runAmbiguityProbe(t *testing.T, sessions int) string {
	t.Helper()
	env := NewFeatureBranchEnv(t)
	env.InitEntire()
	env.PatchSettings(map[string]any{"log_level": "DEBUG"})

	// wt for each session, plus one to commit in.
	first := addLinkedWorktree(t, env, "wt/s0")
	dirs := []string{first}
	for i := 1; i < sessions; i++ {
		dirs = append(dirs, addPlainWorktree(t, env, "wt/s"+string(rune('0'+i)), "s"+string(rune('0'+i))))
	}
	commitIn := addPlainWorktree(t, env, "wt/commit", "commitwt")

	runner := NewHookRunner(env.RepoDir, env.ClaudeProjectDir, t)
	for i, d := range dirs {
		s := env.NewSession()
		if err := runner.SimulateUserPromptSubmitWithCwd(s.ID, "work", s.TranscriptPath, d); err != nil {
			t.Fatal(err)
		}
		p := filepath.Join(d, touchedFile)
		if err := os.WriteFile(p, []byte("package main // s\n"), 0o600); err != nil {
			t.Fatal(err)
		}
		s.CreateTranscript("work", []FileChange{{Path: p, Content: "package main // s\n"}})
		if err := runner.SimulateStopWithCwd(s.ID, s.TranscriptPath, d); err != nil {
			t.Fatal(err)
		}
		st, err := env.GetSessionState(s.ID)
		if err != nil {
			t.Fatal(err)
		}
		t.Logf("  session %d: WorktreePath=%s FilesTouched=%v", i, filepath.Base(st.WorktreePath), st.FilesTouched)
	}

	// Commit the SAME path in a worktree with no session of its own.
	if err := os.WriteFile(filepath.Join(commitIn, touchedFile), []byte("package main // committed\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	worktreeGit(t, commitIn, "add", touchedFile)
	msg := filepath.Join(commitIn, "MSG")
	if err := os.WriteFile(msg, []byte("commit shared.go\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	prep := exec.CommandContext(context.Background(), getTestBinary(), "hooks", "git", "prepare-commit-msg", msg, "message")
	prep.Dir = commitIn
	prep.Env = env.gitHookEnv()
	po, _ := prep.CombinedOutput()
	if s := strings.TrimSpace(string(po)); s != "" {
		t.Logf("  prepare stderr: %q", s)
	}
	worktreeGit(t, commitIn, "commit", "-F", msg, "--no-gpg-sign")
	post := exec.CommandContext(context.Background(), getTestBinary(), "hooks", "git", "post-commit")
	post.Dir = commitIn
	post.Env = env.gitHookEnv()
	qo, _ := post.CombinedOutput()
	if s := strings.TrimSpace(string(qo)); s != "" {
		t.Logf("  post-commit stderr: %q", s)
	}
	return env.TryGetLatestCheckpointID()
}

func TestProbe_AmbiguityVsOverlap(t *testing.T) {
	t.Run("control_one_session_one_worktree", func(t *testing.T) {
		got := runAmbiguityProbe(t, 1)
		t.Logf(">> CONTROL checkpoint: %q (non-empty proves the fixture CAN mint one)", got)
	})
	t.Run("two_sessions_two_worktrees", func(t *testing.T) {
		got := runAmbiguityProbe(t, 2)
		t.Logf(">> AMBIGUOUS checkpoint: %q", got)
	})
}
GOEOF
