// TestProbe_LinkDecisionDiagnostics reads the post-commit hook's own logs, which
// live under the COMMIT worktree's .entire/logs (the hook runs with cwd there),
// not the main checkout's — the gap that left the earlier probe unexplained.
func TestProbe_LinkDecisionDiagnostics(t *testing.T) {
	env := NewFeatureBranchEnv(t)
	env.InitEntire()
	env.PatchSettings(map[string]any{"log_level": "DEBUG"})
	wtA := addLinkedWorktree(t, env, "wt/a")

	parent := t.TempDir()
	if r, err := filepath.EvalSymlinks(parent); err == nil {
		parent = r
	}
	mk := func(name, branch string) string {
		d := filepath.Join(parent, name)
		worktreeGit(t, env.RepoDir, "worktree", "add", "-b", branch, d)
		return d
	}
	wtB := mk("b", "wt/b")
	commitIn := mk("commitwt", "wt/commit")

	runner := NewHookRunner(env.RepoDir, env.ClaudeProjectDir, t)
	for _, d := range []string{wtA, wtB} {
		s := env.NewSession()
		if err := runner.SimulateUserPromptSubmitWithCwd(s.ID, "work", s.TranscriptPath, d); err != nil {
			t.Fatal(err)
		}
		p := filepath.Join(d, "shared.go")
		if err := os.WriteFile(p, []byte("package main // s\n"), 0o600); err != nil {
			t.Fatal(err)
		}
		s.CreateTranscript("work", []FileChange{{Path: p, Content: "package main // s\n"}})
		if err := runner.SimulateStopWithCwd(s.ID, s.TranscriptPath, d); err != nil {
			t.Fatal(err)
		}
		st, _ := env.GetSessionState(s.ID)
		t.Logf(">> session at %s: files=%v", filepath.Base(st.WorktreePath), st.FilesTouched)
	}

	if err := os.WriteFile(filepath.Join(commitIn, "shared.go"), []byte("package main // s\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	worktreeGit(t, commitIn, "add", "shared.go")
	msg := filepath.Join(commitIn, "MSG")
	if err := os.WriteFile(msg, []byte("commit shared\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	for _, args := range [][]string{
		{"hooks", "git", "prepare-commit-msg", msg, "message"},
	} {
		c := exec.CommandContext(context.Background(), getTestBinary(), args...)
		c.Dir = commitIn
		c.Env = env.gitHookEnv()
		o, _ := c.CombinedOutput()
		if s := strings.TrimSpace(string(o)); s != "" {
			t.Logf(">> %v stderr: %q", args[2], s)
		}
	}
	worktreeGit(t, commitIn, "commit", "-F", msg, "--no-gpg-sign")
	post := exec.CommandContext(context.Background(), getTestBinary(), "hooks", "git", "post-commit")
	post.Dir = commitIn
	post.Env = env.gitHookEnv()
	o, _ := post.CombinedOutput()
	if s := strings.TrimSpace(string(o)); s != "" {
		t.Logf(">> post-commit stderr: %q", s)
	}
	t.Logf(">> v1 checkpoint: %q", env.TryGetLatestCheckpointID())

	// THE LOGS THAT MATTER: the commit worktree's, not the main checkout's.
	for _, root := range []struct{ name, dir string }{{"COMMIT-WT", commitIn}, {"main", env.RepoDir}} {
		logs, _ := filepath.Glob(filepath.Join(root.dir, ".entire", "logs", "*.log"))
		t.Logf("---- %s logs: %d file(s) ----", root.name, len(logs))
		for _, lp := range logs {
			b, _ := os.ReadFile(lp)
			for _, line := range strings.Split(string(b), "\n") {
				if strings.Contains(line, "session") && (strings.Contains(line, "match") ||
					strings.Contains(line, "ancestry") || strings.Contains(line, "link") ||
					strings.Contains(line, "condens") || strings.Contains(line, "post-commit")) {
					if i := strings.Index(line, `"msg":"`); i >= 0 {
						t.Logf("   %s", line[i:min(i+180, len(line))])
					}
				}
			}
		}
	}
}
