// resolveEventWorktreeRoot turns the event's working directory into a worktree
// root, and refuses it unless it belongs to the same repository as sessionRoot.
//
// The gate is the git COMMON dir, not the worktree root or the git dir: linked
// worktrees of one repository share a common dir and separate repositories
// never do, which is exactly the boundary worth allowing across. It matters
// because event.CWD arrives in a hook payload — an agent that was told to work
// somewhere else reports that honestly — and the root it produces decides where
// a transcript is written and which repository is inspected.
func resolveEventWorktreeRoot(ctx context.Context, eventCWD, sessionRoot string) (string, bool) {
	logCtx := logging.WithComponent(ctx, "lifecycle")

	eventRoot, err := gitOutputIn(ctx, eventCWD, "rev-parse", "--show-toplevel")
	if err != nil || eventRoot == "" {
		logging.Debug(logCtx, "event worktree: cwd is not inside a repository, staying put",
			slog.String("event_cwd", eventCWD))
		return "", false
	}

	eventCommon, err := gitCommonDirIn(ctx, eventRoot)
	if err != nil || eventCommon == "" {
		logging.Debug(logCtx, "event worktree: common dir unresolved for event cwd, staying put",
			slog.String("event_cwd", eventCWD))
		return "", false
	}
	sessionCommon, err := gitCommonDirIn(ctx, sessionRoot)
	if err != nil || sessionCommon == "" {
		logging.Debug(logCtx, "event worktree: common dir unresolved for session root, staying put",
			slog.String("session_root", sessionRoot))
		return "", false
	}

	if eventCommon != sessionCommon {
		logging.Warn(logCtx, "event worktree: cwd belongs to a different repository, ignoring it",
			slog.String("event_cwd", eventCWD),
			slog.String("event_common_dir", eventCommon),
			slog.String("session_common_dir", sessionCommon))
		return "", false
	}

	return filepath.Clean(eventRoot), true
}

// gitCommonDirIn resolves the git common directory for dir, absolutised against
// dir because git reports it relative to the directory it was asked from.
func gitCommonDirIn(ctx context.Context, dir string) (string, error) {
	out, err := gitOutputIn(ctx, dir, "rev-parse", "--git-common-dir")
	if err != nil {
		return "", err
	}
	if out == "" {
		return "", nil
	}
	if !filepath.IsAbs(out) {
		out = filepath.Join(dir, out)
	}
	resolved, err := filepath.EvalSymlinks(out)
	if err != nil {
		// Not resolvable is not the same as not equal; fall back to the
		// lexical path so a comparison is still possible.
		return filepath.Clean(out), nil //nolint:nilerr // deliberate: comparison still works lexically
	}
	return resolved, nil
}

